  "test": "import request from 'supertest';
import { beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app';
import { createDb, type DB } from '../src/db';

let db: DB;
let app: ReturnType<typeof createApp>;

beforeEach(() => {
  db = createDb();
  app = createApp(db);
  app.get('/error-test', () => {
    throw new Error('Database connection failed: internal details');
  });
});

describe('seguridad de errores', () => {
  it('no expone el stack trace ni mensajes internos en errores 500', async () => {
    const res = await request(app).get('/error-test');
    expect(res.status).toBe(500);
    expect(res.body).toEqual({ error: 'INTERNAL_ERROR' });
    expect(res.body.stack).toBeUndefined();
    expect(res.body.message).toBeUndefined();
  });
});
